import { CommonModule } from '@angular/common';
import { ChangeDetectorRef, Component } from '@angular/core';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { UserlistComponent } from '../userlist/userlist.component';
import { MatDialog } from '@angular/material/dialog';
import { assignedUsersResponce, assignteamReq, teamListResponce } from '../../../interfaces/teamsetup.interface';
import { TeamsetupService } from '../../../services/teamsetup/teamsetup.service';
import { ActivatedRoute } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { CaseBuilderService } from '../../../services/case-builder/case-builder.service';
import { HeaderService } from '../../../../core/services/header/header.service';
import { CdkDropListGroup } from '@angular/cdk/drag-drop';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { DialogueComponent } from '../../../../shared/components/dialogue/dialogue.component';
import { Subscription } from 'rxjs';
import { CommunicationService } from '../../../../shared/services/communication/communication.service';
import { TeamlistComponent } from '../teamlist/teamlist.component';
import { CasedetailService } from '../../../../shared/services/casedetail/casedetail.service';
import { UserPermissionService } from '../../../../shared/services/user-permission/user-permission.service';
@Component({
  selector: 'app-teamsetup',
  standalone: true,
  imports: [CommonModule, FormsModule, ButtonComponent, AvatarComponent, UserlistComponent, TeamlistComponent,
    CdkDropListGroup],
  templateUrl: './teamsetup.component.html',
  styleUrl: './teamsetup.component.scss'
})
export class TeamsetupComponent {
  private evsubscription: Subscription;
  scrolled: boolean = true;
  reached: boolean = true;
  isLoading: boolean = false;
  isloading: boolean = true;
  nCaseid;
  teamlist: teamListResponce[];
  assignedusers: assignedUsersResponce[] = []
  dragteam: teamListResponce;
  isTeamassign: boolean = false; refreshUser: boolean = false;
  userDetail;
  nUTeamid: string;
  constructor(private ss: SecureStorageService, private dialog: MatDialog, private teamS: TeamsetupService, private route: ActivatedRoute,
    private caseS: CasedetailService, private hs: HeaderService, private cf: CommonfunctionService, private cs: CommunicationService,
    private cdr: ChangeDetectorRef,
    private userPermissions: UserPermissionService) {
    var params = this.route.snapshot.params;
    params = JSON.parse(atob(params["id"]));
    this.nCaseid = params && params["id"] ? params["id"] : 0;
    userPermissions.userPermissionList(this.nCaseid);
    this.checkEventSub();
  }


  async checkEventSub() {
    this.evsubscription = this.cs.functionCalled$.subscribe(async (data) => {
      if (data == 'ROLE-PERMISSION') {
        var params = { id: this.nCaseid };
        this.cf.goto('/permission/rolepermission', params);
      } else if (data == 'USER-PERMISSION') {
        var params = { id: this.nCaseid };
        this.cf.goto('/permission/userpermission', params);
      }
    })
  }

  ngOnDestroy() {
    this.evsubscription.unsubscribe();
  }

  ngAfterViewInit(): void {
    setTimeout(() => {
      this.hs.updatePath('team setup');
      this.hs.updateisCase(true);
    }, 10);
  }

  async ngOnInit() {
    this.userDetail = await this.ss.getUserInfo();
    if (this.nCaseid) {
      this.getTeamList();
      this.hs.Casedetail = await this.getCaseDetail(this.nCaseid);
    }

  }

  async getCaseDetail(nCaseid) {
    let res: any = await this.caseS.getCaseInfo(nCaseid);
    return res;
  }


  getTeamList() {
    this.teamS.teamList(this.nCaseid).then(res => {
      this.teamlist = res;
      this.isloading = false;
      this.getassignedUsers();
    });
  }


  getassignedUsers() {
    this.teamS.assignedUsers(this.nCaseid).then(res => {
      this.assignedusers = res;
      if (this.assignedusers.find(e => e.u == this.userDetail.nUserid)) {
        this.nUTeamid = this.assignedusers.find(e => e.u == this.userDetail.nUserid).t;
      }
    });
  }


  onScroll(flag, ev) {
    this.reached = flag ? true : false;
  }

  setSearch($event) {
    console.log($event)
  }


  userChange(e) {
    if (e.type == 'drag') {
      this.isTeamassign = true;
      this.dragteam = null
      if (e.user && e.user.u && e.user.t) {
        var ind = this.assignedusers.findIndex(auser => auser.u == e.user.u);
        if (ind > -1) {
          this.assignedusers[ind]["t"] = e.user.t
        } else {
          this.assignedusers.push(e.user)
        }
      }
    }
    if (e.type == 'dragrm') {
      this.isTeamassign = true;
      var ind = this.assignedusers.findIndex(auser => auser.u == e.user.u);
      this.assignedusers.splice(ind, 1);
    }
  }

  teamChange(e) {
    if (e.type == 'dragteam') {
      this.dragteam = e.dragteam
      return;
    }
    if (e == 'UPDATE') {
      this.teamS.teamList(this.nCaseid).then(res => {
        this.teamlist = res;
      });

    } else if (e == "CREATE-USER") {
      this.getassignedUsers();
    }
    this.cdr.detectChanges()
  }


  getColor(cClr) {
    return cClr ? cClr.substring(0, 7).toUpperCase() : ''
  }

  /** Strict v1–v5 UUID shape. Backend's @IsItUUID() pipes reject anything else
   *  with HTTP 400, so we filter the same set client-side instead of sending
   *  rows the server is guaranteed to refuse. */
  private static readonly UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

  /** Build the assignteam payload with only well-formed (UUID-shaped) rows.
   *  Logs anything dropped so upstream — wherever non-UUID `u`/`t` values are
   *  sneaking into `assignedusers` — can be traced. Cause is usually a stale
   *  draft user record or an entry pushed before the user was saved. */
  private buildAssignTeamPayload(): assignteamReq {
    const re = TeamsetupComponent.UUID_RE;
    const valid: { u: string; t: string }[] = [];
    const dropped: any[] = [];
    for (const u of this.assignedusers) {
      if (re.test(u.u || '') && re.test(u.t || '')) {
        valid.push({ u: u.u, t: u.t });
      } else {
        dropped.push(u);
      }
    }
    if (dropped.length) {
      console.warn('[teamsetup] dropped non-UUID assignedusers rows:', dropped);
    }
    return { nCaseid: this.nCaseid, jUsers: valid };
  }

  submitTeam() {
    if (this.isTeamassign) {
      if (this.assignedusers.find(u => u.u == this.userDetail.nUserid)) {
        this.isLoading = true;
        var params: assignteamReq = this.buildAssignTeamPayload();
        this.teamS.assignTeam(params).then(res => {
          if (res) {
            this.isLoading = false;
            this.cf.goto('managefiles/bundlemanagement', { id: this.nCaseid })
          }
        });
      } else {
        this.openalert(data => {
          if (data.res) {
            this.isLoading = true;
            var params: assignteamReq = this.buildAssignTeamPayload();
            this.teamS.assignTeam(params).then(res => {
              if (res) {
                this.isLoading = false;
                this.cf.goto('managefiles/bundlemanagement', { id: this.nCaseid })
              }
            });
          }
        });
      }
    } else {
      this.isLoading = false;
      this.skip();
    }
  }

  skip() {
    if (!this.assignedusers.find(auser => auser.u == this.userDetail.nUserid)) {
      this.openalert(data => {
        if (data.res) {
          this.cf.goto('managefiles/bundlemanagement', { id: this.nCaseid })
        }
      });
    } else {
      this.cf.goto('managefiles/bundlemanagement', { id: this.nCaseid })
    }
  }


  openalert(cb) {
    const dialogRef = this.dialog.open(DialogueComponent, {
      width: 'fit-content',
      minWidth: '500px',
      height: 'fit-content',
      data: {
        'type': 'E', // 'I'
        'heading': 'Assign yourself first for a full access to this case',
        'desc': 'To access dashboard, upload and make edits.',
        'button1': 'I will do it now',
        'button2': 'Go to HearingHub',
        'bt1res': false,
        'bt2res': true,
        'checkbox': 'Don’t show this again.',
      }
    });
    dialogRef.afterClosed().subscribe(result => {
      cb(result)
    })
  }

}




