import { ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges, input } from '@angular/core';
import { teamListResponce } from '../../../interfaces/teamsetup.interface';
import { SkeletonComponent } from '../../../../shared/components/skeleton/skeleton.component';
import { CdkDragPlaceholder, DragDropModule } from '@angular/cdk/drag-drop';
import { CommonModule } from '@angular/common';
import { TeamcreationComponent } from '../teamcreation/teamcreation.component';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { TeamsetupService } from '../../../services/teamsetup/teamsetup.service';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { MatMenuModule } from '@angular/material/menu';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { UsercreationComponent } from '../usercreation/usercreation.component';
import { UserDetail } from '../../../../core/interfaces/login.interface';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { CommunicationService } from '../../../../shared/services/communication/communication.service';

@Component({
  selector: 'teamlist',
  standalone: true,
  imports: [CommonModule, DragDropModule, CdkDragPlaceholder, SkeletonComponent, MatDialogModule, IconComponent, ButtonComponent, MatMenuModule,],
  templateUrl: './teamlist.component.html',
  styleUrl: './teamlist.component.scss'
})
export class TeamlistComponent {
  dragteam: teamListResponce;
  isdraging: boolean = false;
  @Input() teamlist: teamListResponce[];
  @Output() teamChange: EventEmitter<string> = new EventEmitter();
  @Input() nCaseid: string;
  @Input() isloading: boolean;
  @Input() nUTeamid: string;

  userInfo: UserDetail;
  constructor(private teamS: TeamsetupService, private dialog: MatDialog
    , private ss: SecureStorageService, private cdr: ChangeDetectorRef,
    private cs: CommunicationService
  ) {
    this.getUserInfo()
  }

  async getUserInfo() {
    this.userInfo = await this.ss.getUserInfo();
  }

  dragStarted(event: any, x) {
    this.dragteam = x;
    var res: any = { type: 'dragteam', dragteam: this.dragteam }
    this.teamChange.emit(res)
  }

  onDraging(ev) {
    var dragval = Math.abs(ev.distance.y);
    if (dragval > 0) {
      this.isdraging = true;
    } else {
      this.isdraging = false;
    }
  }

  dropListPredicate() {
    return function () { return false };
  }


  ngOnChanges(changes: SimpleChanges) {
    this.cdr.detectChanges()
  }

  getColor(cClr) {
    return cClr ? cClr.substring(0, 7).toUpperCase() : ''
  }


  createTeam(x?) {
    var data: object = {
      nCaseid: this.nCaseid,
      nTeamid: x && x.nTeamid ? x.nTeamid : null,
      cTeamname: x && x.cTeamname ? x.cTeamname : null,
      cClr: x && x.cClr ? x.cClr : null
    }
    this.openModle(TeamcreationComponent, data, '485px')
  }


  createUser(x?) {
    var data = {
      nCaseid: this.nCaseid,
      nUserid: x && x.nUserid ? x.nUserid : null,
      nUTeamid: this.nUTeamid
    }
    this.openModle(UsercreationComponent, data)
  }

  openModle(component, data: object, width?: string, height?: string, x?) {
    const dialogRef = this.dialog.open(component, {
      width: width ? width : 'fit-content',
      height: height ? height : 'fit-content',
      maxHeight: '99vh',
      panelClass: ['addusermodal', 'rounded-10', 'overflow-hidden'],
      data: data
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result && result["isSave"]) {
        if (component == TeamcreationComponent) {
          this.teamChange.emit('UPDATE');
        } if (component == UsercreationComponent) {
          this.teamChange.emit('CREATE-USER');
          if (!this.userInfo.isAdmin) {
            this.cs.callFunction('USER-RELOAD')
          }
        }
      }
      console.log(result);
    })
  }

  async deleteTeam(x) {
    let res: any = await this.teamS.teamDelete({ nTeamid: x.nTeamid });
    if (res) {
      this.teamChange.emit('UPDATE');
    }
  }


}
