import { CommonModule } from '@angular/common';
import { Component, EventEmitter, HostListener, Inject, Output } from '@angular/core';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { InputComponent } from '../../../../shared/components/input/input.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { ThemePalette } from '@angular/material/core';
import { AbstractControl, UntypedFormControl } from '@angular/forms';
import { ColorpickerComponent } from '../../../../shared/components/colorpicker/colorpicker.component';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { TeamsetupService } from '../../../services/teamsetup/teamsetup.service';
import { teamBuilderReq, teamColorResponce } from '../../../interfaces/teamsetup.interface';
import { HttpClientModule } from '@angular/common/http';

@Component({
  selector: 'app-teamcreation',
  standalone: true,
  //  providers: [TeamsetupService],
  imports: [CommonModule, IconComponent, InputComponent, ButtonComponent, ColorpickerComponent],
  templateUrl: './teamcreation.component.html',
  styleUrl: './teamcreation.component.scss'
})
export class TeamcreationComponent {

  @HostListener('document:mousemove', ['$event'])

  onMouseMove(e) {
    try {
      var qsa: any = document.querySelectorAll('.color-picker .cursor')[1];
      qsa.style.background = this.arrayColors_tag.color1;
    } catch (error) {
    }
  }

  public disabled = false;
  public color: ThemePalette = 'primary';
  public touchUi = false;
  cTeamname: string = '';
  colorCtr: AbstractControl = new UntypedFormControl(null);
  public options = [
    { value: true, label: 'True' },
    { value: false, label: 'False' }
  ];

  public listColors = ['primary', 'accent', 'warn'];

  frm: any;
  showsubtag: boolean = false;
  public arrayColors_tag: any = {
    color1: '#2883e9',
    color2: '#e920e9',
    color3: 'rgb(255,245,0)',
    color4: 'rgb(236,64,64)',
    color5: 'rgba(45,208,45,1)',
  };
  public selectedColor_tag: string = 'color1';
  @Output() fromassignee = new EventEmitter<String>();
  nTeamid: any;
  formsubmit: boolean = false;
  showconfpop: boolean = false;
  issuecategory: any = [];
  cClr: string = '#ff9163ff';
  pickcolor: boolean = false;
  isCreating: boolean = false;
  permission: string = 'N';
  nCaseid: string;
  colorslist: teamColorResponce[]
  constructor(private dialogRef: MatDialogRef<TeamcreationComponent>, @Inject(MAT_DIALOG_DATA) public data: any, private teamS: TeamsetupService) {
    this.nCaseid = data['nCaseid'];
    this.nTeamid = data['nTeamid'];
    if (this.nTeamid) {
      this.permission = 'E';
      this.cTeamname = data['cTeamname'];
      this.cClr = data['cClr'];
    }
  }

  ngOnInit() {
    this.teamS.teamColor(this.nCaseid).then(res => {
      this.colorslist = res;
    });
  }

  async onSubmit() {

    if (this.cTeamname.trim() != '') {
      var mdl: teamBuilderReq = { nCaseid: this.nCaseid, nTeamid: this.nTeamid ? this.nTeamid : 0, cTeamname: this.cTeamname, cClr: this.cClr, permission: this.permission };
      let res: any = await this.teamS.teamBuilder(mdl);
      if (res) {
        this.dialogRef.close({ isSave: true })
        // this.router.navigate(['/casebuilder/bundlemanagement']);
      }
    }
  }

  close() {
    this.dialogRef.close()
  }
}
